// Package crew is small-group coordination as a product rather than as a
// framework: three to fifteen people with a shared pot, a way to decide, and a
// way to leave with their share.
//
// # Why not a DAO framework
//
// A framework asks you to pick a governance module, a voting strategy and a
// treasury adapter before anybody has put in a single ugnot. The targets here
// are real and already exist: a validator set, a working group, a hackathon
// team, a five-person company. They want the thing you can create in one
// transaction. [gno.land/p/nym-moultest123/grants] and daokit are the framework layer, and
// this package is deliberately underneath them: one call to open a crew, one to
// join it, one to leave with what your shares are worth.
//
// # The model
//
//	Crews     every crew, plus the credit ledger every payout goes through
//	Crew      a name, a creation height, members with shares, a treasury, proposals
//	Proposal  advisory text with a deadline and a share-weighted tally
//
// Shares are the whole design. They are the vote weight and the claim on the
// treasury at the same time, minted by [Crews.Join] and burned by
// [Crews.Ragequit], so leaving is priced by the same number that decides. There
// is no separate token to issue, distribute or forget to make meaningful.
//
// # Rounding, which is the part that has to be right
//
// Every division here rounds DOWN, and both of them therefore round in the
// crew's favour:
//
//   - joining mints amount * totalShares / treasury, so a late joiner buys
//     exactly what they paid for at the CURRENT per-share value and never a
//     share more. Rounding up would hand them a sliver of value the existing
//     members built, which is the whole reason a flat price is wrong here.
//   - ragequitting credits shares * treasury / totalShares, so a leaver takes
//     no more than their slice and the remainder stays with the people who
//     stayed.
//
// The dust that accrues from both is never stranded: the last member to
// ragequit holds every outstanding share, so their MulDiv is exact and the
// treasury empties to the last ugnot. [Crews.Ragequit] has a test for that.
//
// # What v0 deliberately does not do
//
// A proposal is advisory text. Passing one executes nothing, moves nothing and
// binds nothing; it records that the crew agreed by share weight at a point in
// time. Executing a payout is the obvious next step and the one that turns this
// into a treasury contract rather than a notice board.
//
// A vote is weighed at the moment it is cast. A member who votes and then
// ragequits leaves their weight behind in the tally, because unwinding it would
// mean re-weighing every ballot on every share change.
//
// # Errors, not aborts
//
// This is a p/, so it returns errors and declares no crossing function: the
// caller, the height and the amount all arrive as plain arguments and the realm
// that wires it to the chain decides what to abort on.
package crew

import (
	"chain/markdown"
	"errors"
	"strings"

	"gno.land/p/nym-moultest123/kit/store/v0"
	"gno.land/p/nym-moultest123/xmath/v1"
)

const (
	// MaxMembers is the upper end of "three to fifteen people". It is a
	// product constraint and not a technical one: above it the share math
	// still works and the thing stops being a crew.
	MaxMembers = 15

	// InitialPricePerShare is what a share costs in ugnot before the crew
	// has a treasury to price against: at creation, and again if every
	// member has left. 1000 ugnot makes 1 GNOT worth 1000 shares, which
	// keeps the integer arithmetic far away from both zero and overflow.
	InitialPricePerShare = int64(1000)

	// VoteBlocks is how long a proposal stays open, in blocks.
	VoteBlocks = int64(1000)

	// MaxNameLen and MaxTextLen bound what one call can make the crew's
	// members pay a storage deposit on.
	MaxNameLen = 60
	MaxTextLen = 500

	// ExcerptLen is how much of a proposal a listing shows.
	ExcerptLen = 60
)

// maxInt64 is the largest int64, spelled out because the overflow guards
// compare against it directly.
const maxInt64 = int64(9223372036854775807)

// The errors a caller can get back.
var (
	ErrBadName     = errors.New("crew: name is empty, too long, or has control characters")
	ErrBadText     = errors.New("crew: text is empty, too long, or has control characters")
	ErrBadAmount   = errors.New("crew: amount must be positive")
	ErrNoCrew      = errors.New("crew: no such crew")
	ErrNoProposal  = errors.New("crew: no such proposal")
	ErrNotMember   = errors.New("crew: not a member of this crew")
	ErrIsMember    = errors.New("crew: already a member of this crew")
	ErrFull        = errors.New("crew: the crew is full")
	ErrNoShares    = errors.New("crew: the amount sent buys no whole share")
	ErrVoteClosed  = errors.New("crew: the proposal is no longer open")
	ErrVoteOpen    = errors.New("crew: the proposal is still open")
	ErrNothing     = errors.New("crew: nothing to withdraw")
	ErrWouldExceed = errors.New("crew: the amount would overflow the ledger")
)

// Crew is one group: who is in it, what it holds, and what it is deciding.
type Crew struct {
	Name      string
	CreatedAt int64 // block height
	Treasury  int64 // ugnot, accounted here and held at the realm's address

	// TotalShares is every share outstanding. It is the denominator of both
	// the join price and the ragequit payout, so it is maintained here
	// rather than summed over the members on demand.
	TotalShares int64

	shares    map[string]int64 // address -> shares held
	order     []address        // members in join order, so output never iterates a map
	proposals []store.ID
}

// SharesOf is how many shares who holds, zero when they hold none.
func (c *Crew) SharesOf(who address) int64 {
	if c == nil {
		return 0
	}
	return c.shares[who.String()]
}

// IsMember reports whether who holds any share.
func (c *Crew) IsMember(who address) bool { return c.SharesOf(who) > 0 }

// MemberCount is how many addresses hold shares.
func (c *Crew) MemberCount() int {
	if c == nil {
		return 0
	}
	return len(c.order)
}

// Members returns the members in join order. The slice is a copy, so a caller
// rendering it cannot reorder the crew.
func (c *Crew) Members() []address {
	if c == nil {
		return nil
	}
	out := make([]address, len(c.order))
	copy(out, c.order)
	return out
}

// Proposals returns this crew's proposal ids, oldest first, as a copy.
func (c *Crew) Proposals() []store.ID {
	if c == nil {
		return nil
	}
	out := make([]store.ID, len(c.proposals))
	copy(out, c.proposals)
	return out
}

// ValuePerShare is what one share is worth in ugnot right now, rounded down.
//
// It is a display figure and nothing computes against it: [Crews.Join] and
// [Crews.Ragequit] divide by the real totals, so a crew whose treasury is
// smaller than its share count still prices both correctly while this reads 0.
func (c *Crew) ValuePerShare() int64 {
	if c == nil || c.TotalShares == 0 {
		return 0
	}
	return c.Treasury / c.TotalShares
}

// PricePerShare is what the next share costs a joiner, rounded down, which is
// [Crew.ValuePerShare] except on a crew nobody holds a share in.
func (c *Crew) PricePerShare() int64 {
	if c == nil || c.TotalShares == 0 || c.Treasury == 0 {
		return InitialPricePerShare
	}
	return c.Treasury / c.TotalShares
}

// ballot is one member's vote: which way, and what it weighed when cast.
type ballot struct {
	yes    bool
	weight int64
}

// Proposal is a question put to a crew. v0 proposals are advisory text and
// execute nothing: see the package doc.
type Proposal struct {
	CrewID   store.ID
	Author   address
	Text     string
	OpenedAt int64
	Deadline int64 // OpenedAt + VoteBlocks, exclusive

	// Yes and No are the running share-weighted tally, maintained on every
	// vote so reading it never walks the ballots.
	Yes int64
	No  int64

	Closed bool
	Passed bool

	votes map[string]ballot
}

// Open reports whether the proposal still accepts votes at height now.
func (p *Proposal) Open(now int64) bool {
	return p != nil && !p.Closed && now < p.Deadline
}

// VoteOf reports how who voted and what it weighed, and whether they voted at
// all.
func (p *Proposal) VoteOf(who address) (yes bool, weight int64, voted bool) {
	if p == nil {
		return false, 0, false
	}
	b, ok := p.votes[who.String()]
	return b.yes, b.weight, ok
}

// Voters is how many members have cast a ballot.
func (p *Proposal) Voters() int {
	if p == nil {
		return 0
	}
	return len(p.votes)
}

// Crews holds every crew, every proposal, and the credit ledger each payout
// goes through.
type Crews struct {
	crews *store.Store
	props *store.Store

	credit map[string]int64 // address -> ugnot owed
	owed   int64            // the sum of the above, which the holder must reserve
}

// New returns an empty Crews.
func New() *Crews {
	return &Crews{
		crews:  store.Named("crew"),
		props:  store.Named("proposal"),
		credit: map[string]int64{},
	}
}

// Create opens a crew with founder as its only member, their shares bought out
// of amount at [InitialPricePerShare].
//
// The remainder below one whole share stays in the treasury rather than being
// refunded, which is the same direction every other division here rounds.
func (cs *Crews) Create(name string, founder address, amount, at int64) (store.ID, error) {
	if !ValidName(name) {
		return 0, ErrBadName
	}
	if amount <= 0 {
		return 0, ErrBadAmount
	}
	shares := amount / InitialPricePerShare
	if shares < 1 {
		return 0, ErrNoShares
	}
	c := &Crew{
		Name:        name,
		CreatedAt:   at,
		Treasury:    amount,
		TotalShares: shares,
		shares:      map[string]int64{founder.String(): shares},
		order:       []address{founder},
	}
	return cs.crews.Add(c), nil
}

// Join mints who shares at the crew's CURRENT per-share value and adds amount
// to its treasury.
//
// amount * totalShares / treasury, rounded down. That is the whole anti-dilution
// rule: a crew that turned 10 GNOT into 20 sells the next share for what a share
// is worth now, not for what the founders paid, and the rounding remainder stays
// with the crew rather than with the joiner.
func (cs *Crews) Join(id store.ID, who address, amount int64) (int64, error) {
	c, ok := cs.Get(id)
	if !ok {
		return 0, ErrNoCrew
	}
	if amount <= 0 {
		return 0, ErrBadAmount
	}
	if c.IsMember(who) {
		return 0, ErrIsMember
	}
	if len(c.order) >= MaxMembers {
		return 0, ErrFull
	}
	if c.Treasury > maxInt64-amount {
		return 0, ErrWouldExceed
	}

	var shares int64
	if c.TotalShares == 0 || c.Treasury == 0 {
		// Nobody holds a share, so there is no value to price against and
		// the crew is back at its opening price.
		shares = amount / InitialPricePerShare
	} else {
		shares = xmath.MulDiv(amount, c.TotalShares, c.Treasury)
	}
	if shares < 1 {
		return 0, ErrNoShares
	}
	if c.TotalShares > maxInt64-shares {
		return 0, ErrWouldExceed
	}

	c.shares[who.String()] = shares
	c.order = append(c.order, who)
	c.TotalShares += shares
	c.Treasury += amount
	return shares, nil
}

// Fund adds amount to a crew's treasury and mints nothing.
//
// It is what makes the join price mean anything: a crew whose treasury only
// ever moves with its share count prices every joiner identically forever, and
// the anti-dilution rule in [Crews.Join] would be decorative. Revenue, a grant
// and a member topping the pot up all arrive this way, and every existing share
// is worth more afterwards.
func (cs *Crews) Fund(id store.ID, amount int64) error {
	c, ok := cs.Get(id)
	if !ok {
		return ErrNoCrew
	}
	if amount <= 0 {
		return ErrBadAmount
	}
	if c.Treasury > maxInt64-amount {
		return ErrWouldExceed
	}
	c.Treasury += amount
	return nil
}

// Propose opens an advisory question, open for [VoteBlocks] blocks. Any member
// may propose.
func (cs *Crews) Propose(id store.ID, who address, text string, at int64) (store.ID, error) {
	c, ok := cs.Get(id)
	if !ok {
		return 0, ErrNoCrew
	}
	if !c.IsMember(who) {
		return 0, ErrNotMember
	}
	if !ValidText(text) {
		return 0, ErrBadText
	}
	p := &Proposal{
		CrewID:   id,
		Author:   who,
		Text:     text,
		OpenedAt: at,
		Deadline: at + VoteBlocks,
		votes:    map[string]ballot{},
	}
	pid := cs.props.Add(p)
	c.proposals = append(c.proposals, pid)
	return pid, nil
}

// Vote records who's ballot, weighted by the shares they hold right now.
//
// One ballot per member, changeable while the proposal is open: a second call
// replaces the first, tally and weight both, so changing your mind after buying
// more shares counts the shares you now hold.
func (cs *Crews) Vote(pid store.ID, who address, yes bool, at int64) error {
	p, ok := cs.Proposal(pid)
	if !ok {
		return ErrNoProposal
	}
	if !p.Open(at) {
		return ErrVoteClosed
	}
	c, ok := cs.Get(p.CrewID)
	if !ok {
		return ErrNoCrew
	}
	weight := c.SharesOf(who)
	if weight <= 0 {
		return ErrNotMember
	}

	key := who.String()
	if prev, voted := p.votes[key]; voted {
		if prev.yes {
			p.Yes -= prev.weight
		} else {
			p.No -= prev.weight
		}
	}
	p.votes[key] = ballot{yes: yes, weight: weight}
	if yes {
		p.Yes += weight
	} else {
		p.No += weight
	}
	return nil
}

// Close records a proposal as passed or failed by share weight, once its
// deadline has gone by. Anyone may call it: closing is bookkeeping, not
// authority, and a proposal nobody closes is simply never recorded.
//
// A tie fails. There is no quorum in v0: a crew where one member votes and the
// rest ignore it passes the proposal, which is exactly as advisory as the text
// it carries.
func (cs *Crews) Close(pid store.ID, at int64) (bool, error) {
	p, ok := cs.Proposal(pid)
	if !ok {
		return false, ErrNoProposal
	}
	if p.Closed {
		return p.Passed, ErrVoteClosed
	}
	if at < p.Deadline {
		return false, ErrVoteOpen
	}
	p.Closed = true
	p.Passed = p.Yes > p.No
	return p.Passed, nil
}

// Ragequit burns every share who holds, credits them their pro-rata slice of
// the treasury and removes them from the crew.
//
// shares * treasury / totalShares, rounded down, so the remainder stays with
// the members who stayed. This is what makes a share mean something: the exit
// is priced by the same number that votes, and nobody has to agree to let you
// out.
//
// The payout is credited, never sent. The caller moves the coins after this
// returns, which is the ordering the pull-payment pattern exists for.
func (cs *Crews) Ragequit(id store.ID, who address) (shares, amount int64, err error) {
	c, ok := cs.Get(id)
	if !ok {
		return 0, 0, ErrNoCrew
	}
	shares = c.SharesOf(who)
	if shares <= 0 {
		return 0, 0, ErrNotMember
	}

	amount = xmath.MulDiv(shares, c.Treasury, c.TotalShares)
	c.TotalShares -= shares
	c.Treasury -= amount
	delete(c.shares, who.String())
	c.order = dropAddress(c.order, who)

	if amount > 0 {
		if err := cs.credits(who, amount); err != nil {
			return 0, 0, err
		}
	}
	return shares, amount, nil
}

// credits adds to an address's withdrawable balance.
func (cs *Crews) credits(who address, amount int64) error {
	key := who.String()
	if cs.credit[key] > maxInt64-amount || cs.owed > maxInt64-amount {
		return ErrWouldExceed
	}
	cs.credit[key] += amount
	cs.owed += amount
	return nil
}

// Withdraw zeroes who's credit and returns what they were owed.
//
// The balance is gone from the ledger before this returns, so the caller can
// move the coins afterwards and a reentrant call finds nothing: effects, then
// interactions.
func (cs *Crews) Withdraw(who address) (int64, error) {
	key := who.String()
	amount, ok := cs.credit[key]
	if !ok || amount == 0 {
		return 0, ErrNothing
	}
	delete(cs.credit, key)
	cs.owed -= amount
	return amount, nil
}

// CreditOf is what who can withdraw right now.
func (cs *Crews) CreditOf(who address) int64 { return cs.credit[who.String()] }

// TotalOwed is the sum of every outstanding credit, which is what the holding
// realm must keep in reserve on top of every crew's treasury.
func (cs *Crews) TotalOwed() int64 { return cs.owed }

// Get returns a crew by id.
func (cs *Crews) Get(id store.ID) (*Crew, bool) {
	v, ok := cs.crews.Get(id)
	if !ok {
		return nil, false
	}
	return v.(*Crew), true
}

// Proposal returns a proposal by id.
func (cs *Crews) Proposal(pid store.ID) (*Proposal, bool) {
	v, ok := cs.props.Get(pid)
	if !ok {
		return nil, false
	}
	return v.(*Proposal), true
}

// Len is how many crews exist.
func (cs *Crews) Len() int { return cs.crews.Len() }

// ProposalCount is how many proposals exist, across every crew.
func (cs *Crews) ProposalCount() int { return cs.props.Len() }

// Listing is one row of [Crews.List]: the crew and the id a link needs.
type Listing struct {
	ID   store.ID
	Crew *Crew
}

// List returns up to limit crews, newest first. limit below 1 returns nothing.
func (cs *Crews) List(limit int) []Listing {
	var out []Listing
	for _, e := range cs.crews.PageReverse(1, limit) {
		out = append(out, Listing{ID: e.ID, Crew: e.Value.(*Crew)})
	}
	return out
}

// ValidName reports whether name can be stored: non-empty after the render's
// own stripping and trimming,
// within [MaxNameLen], free of control characters including newlines, and
// free of the pipe character.
//
// The pipe is the one restriction that is not obvious, and it is here because
// a name is rendered as the TITLE of a link inside a table cell. md.Link
// escapes its title with the inline-text escaper, which deliberately leaves
// "|" alone because a pipe is markdown-inert outside a table, and wrapping the
// title in ui.Cell on top of that would double-escape and render the
// backslashes. Refusing the character at write time is the only place left
// where the fix is one rule rather than one exception per call site.
//
// A proposal's text has no such restriction: [ValidText] allows a pipe and the
// render escapes it with ui.Cell, because free prose legitimately contains one
// and a name does not.
func ValidName(name string) bool {
	if len(name) > MaxNameLen || strings.TrimSpace(markdown.StripBidiAndZeroWidth(name)) == "" {
		return false
	}
	for i := 0; i < len(name); i++ {
		c := name[i]
		if c < 0x20 || c == 0x7f || c == '|' {
			return false
		}
	}
	return true
}

// ValidText reports whether a proposal body can be stored: non-empty after
// the render's own stripping and trimming, within [MaxTextLen], and free of control characters other than
// newline and tab.
//
// Control characters are refused rather than stripped because the text is shown
// back to its author, and silently rewriting what somebody wrote is worse than
// telling them it was refused. Everything else is allowed and escaped at render
// time: a validator and an escaper protect against different mistakes.
func ValidText(text string) bool {
	if len(text) > MaxTextLen || strings.TrimSpace(markdown.StripBidiAndZeroWidth(text)) == "" {
		return false
	}
	for i := 0; i < len(text); i++ {
		c := text[i]
		if c < 0x20 && c != '\n' && c != '\t' || c == 0x7f {
			return false
		}
	}
	return true
}

// dropAddress returns addrs without who, in a freshly allocated slice.
//
// It allocates rather than shortening in place: a slice is one persisted object
// and the storage deposit only comes back when that object is dropped, so
// append(s[:i], s[i+1:]...) would keep the peak allocation charged forever.
func dropAddress(addrs []address, who address) []address {
	out := make([]address, 0, len(addrs))
	for _, a := range addrs {
		if a != who {
			out = append(out, a)
		}
	}
	return out
}

package crew

import "testing"

// Finding 325-input-validation-1 (review run 001-cd0b6a9).
//
// A validator that calls a field required must agree with the escaper its own
// render runs. strings.TrimSpace uses unicode.IsSpace, which does NOT include
// U+200B and the rest of the bidi and zero-width set, while every escaper on
// the output side runs chain/markdown.StripBidiAndZeroWidth, which does. So a
// value made only of those characters passes validation and renders as
// nothing: a required field that is blank on the page.
//
// The cases below are the invariant, not the implementation. A value the
// validator accepts must still be non-empty after the stripper.
func TestValidatorsAgreeWithTheEscaper(t *testing.T) {
	// One per class the stripper removes, so a fix that handles only
	// U+200B does not pass.
	blank := []string{
		"\u200b\u200b\u200b",   // ZWSP
		"\u200d",                // ZWJ
		"\u200e",                // LRM
		"\u202e",                // RLO
		"\u2066\u2069",          // LRI PDI
		"\ufeff",                // BOM
		" \u200b \u200b ",        // mixed with real spaces
	}
	// These must stay valid: the stripper removes the marks and leaves text.
	ok := []string{
		"a",
		"a\u200bb",
		"  padded  ",
	}

	for _, s := range blank {
		if ValidName(s) {
			t.Errorf("ValidName(%q) is true, but the render strips it to empty", s)
		}
	}
	for _, s := range ok {
		if !ValidName(s) {
			t.Errorf("ValidName(%q) is false, but it renders as real text", s)
		}
	}

	for _, s := range blank {
		if ValidText(s) {
			t.Errorf("ValidText(%q) is true, but the render strips it to empty", s)
		}
	}
	for _, s := range ok {
		if !ValidText(s) {
			t.Errorf("ValidText(%q) is false, but it renders as real text", s)
		}
	}

}

package crews

import (
	"strconv"
	"strings"
	"testing"
)

// Finding 325-cost-at-caps-1. A crew's page rendered every proposal the crew
// had ever had. Proposing is open to every member and nothing deletes one, so
// the cost every reader of that page paid grew without a bound anybody
// controls.
//
// Both comparison points are above the cap on purpose: comparing a count below
// it with one above measures the cap arriving, not the page being bounded.
func TestACrewPageIsBoundedByWhatItShows(cur realm, t *testing.T) {
	reset()
	id := create(cur, alice, 1000000, "the crew")

	for i := 0; i < 40; i++ {
		testing.SetRealm(testing.NewUserRealm(alice))
		Propose(cross(cur), id, "proposal number "+strconv.Itoa(i))
	}
	small := Render("crew/" + strconv.FormatInt(id, 10))

	for i := 40; i < 200; i++ {
		testing.SetRealm(testing.NewUserRealm(alice))
		Propose(cross(cur), id, "proposal number "+strconv.Itoa(i))
	}
	big := Render("crew/" + strconv.FormatInt(id, 10))

	rowsSmall := strings.Count(small, "\n|")
	rowsBig := strings.Count(big, "\n|")
	if rowsSmall == 0 {
		t.Fatal("no table rows rendered at all, so this test is measuring nothing")
	}
	if rowsBig > rowsSmall {
		t.Errorf("the crew page grew from %d rows to %d when the proposals went from 40 to 200: "+
			"every reader pays for every proposal the crew has ever had", rowsSmall, rowsBig)
	}
}

// Package crews is small-group coordination you can create in one
// transaction: three to fifteen people with a shared pot, a way to decide, and
// a way to leave with their share.
//
// It is the chain wiring for [gno.land/p/nym-moultest123/x/social/crew], which holds the
// share math and the proposal state. This realm reads the caller, reads the
// coins attached to the call, asks the engine, and renders the result.
//
//	Create    pay in, and you are the crew's first member
//	Join      pay in at what a share is worth NOW, not at what it cost them
//	Fund      pay in and mint nothing, so every existing share is worth more
//	Propose   any member opens an advisory question
//	Vote      weighted by the shares you hold, changeable while it is open
//	Close     anyone, once the deadline has gone by
//	Ragequit  burn your shares, be credited your slice, leave
//	Withdraw  collect what you were credited
//
// # The shares are the token
//
// There is no second asset to issue. A share is the vote weight and the claim
// on the treasury at the same moment, minted by paying in and burned by
// leaving, so nothing about it is decorative and nobody has to be persuaded it
// is worth something. v0 keeps the shares as an internal ledger rather than one
// GRC20 per crew, because a GRC20 per crew means a realm per crew. A
// transferable share belongs in [gno.land/p/nym-moultest123/x/social/coin], the sibling
// that refuses to exist until its mint rule, sink and buyer are declared; this
// realm does not import it.
//
// # The custody caveat, which is real
//
// ONE realm address holds EVERY crew's treasury, with per-crew accounting
// inside it. The chain sees one balance; which crew owns which part of it is a
// number in this realm's state. So a bug in the accounting is a bug across
// crews, not inside one: an arithmetic error that over-credits one crew's
// ragequit pays it out of another crew's money, and nothing at the bank layer
// would refuse that transfer.
//
// The fix is the instance-per-realm pattern (EFFECTIVE_GNO.md section 1.4): one
// realm per crew, each holding its own coins at its own address, with this
// package as the shared engine. That is v1. It is not v0 because deploying a
// realm per crew is a publish per crew, which is the opposite of "create it in
// one transaction", and the whole product claim here is the one transaction.
//
// # Payouts are pulled
//
// Nothing is ever pushed. A ragequit credits an internal ledger and the leaver
// calls [Withdraw] themselves, so one address that cannot be paid cannot wedge
// anybody else, and the credit is zeroed before the coins move.
package crews

import (
	"strconv"

	"chain"
	"chain/banker"
	"chain/runtime"

	"gno.land/p/nym-moultest123/kit/store/v0"
	"gno.land/p/nym-moultest123/x/envelope/v0"
	"gno.land/p/nym-moultest123/x/social/crew/v0"
	"gno.land/p/nym-moultest123/xmath/v1"
)

// realmPath is this realm's own path, the one its gnomod.toml module line
// declares. It is written out rather than read from the runtime, because every
// plain read this realm exports reports its CALLER and would build every link
// against the wrong realm.
const realmPath = "gno.land/r/nym-moultest123/x/social/crews/v0"

// denom is the only coin a crew holds. ugnot and nothing else: a treasury that
// can hold several denominations needs a per-denomination share price, which is
// a different product.
const denom = "ugnot"

// IndexCrews is how many crews the index page lists.
const IndexCrews = 20

// IndexProposals is how many of a crew's proposals its page lists.
//
// Finding 325-cost-at-caps-1: the page rendered every proposal a crew had ever
// had. Proposing is open to every member and nothing deletes one, so the cost
// every reader pays grew without a bound anybody controls.
const IndexProposals = 20

// crews holds every crew, every proposal and the credit ledger. A redeploy
// wipes it, which is the trade gnomod.toml's private = true makes: see the
// comment there.
var crews = crew.New()

// Create opens a crew and makes the caller its first member.
//
// Send ugnot with the call: the founder's shares are bought out of it at
// crew.InitialPricePerShare, and the whole amount, remainder included, becomes
// the treasury. Returns the new crew's id.
func Create(cur realm, name string) int64 {
	// Both checks have to be here and not behind a helper. cur.IsCurrent()
	// before cur.Previous() is the realm-token rule; IsUserCall before the
	// envelope read is the payment one, because the envelope reports what
	// the SIGNER attached to the transaction and not what reached this
	// realm. Without it a realm the user called keeps the coins and calls
	// in here as many times as it likes, every call reading the same send.
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	if !cur.Previous().IsUserCall() {
		panic("crews: paying in must be a direct user transaction")
	}
	who := cur.Previous().Address()
	amount := envelope.RequireAtLeast(denom, crew.InitialPricePerShare)

	id, err := crews.Create(name, who, amount, runtime.ChainHeight())
	if err != nil {
		panic(err.Error())
	}
	chain.Emit("Create",
		"crew", id.String(),
		"founder", who.String(),
		"amount", strconv.FormatInt(amount, 10),
	)
	return int64(id)
}

// Join mints the caller shares at what a share is worth right now and adds what
// they sent to the treasury. Returns the shares minted.
//
// The price is amount * totalShares / treasury, rounded down, so somebody
// joining a crew that has tripled its money pays three times what the founders
// did. Send at least the crew page's join price, treasury / totalShares rounded
// up, or there is no whole share to mint.
func Join(cur realm, crewID int64) int64 {
	// The two guards every payable call needs; see Create.
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	if !cur.Previous().IsUserCall() {
		panic("crews: paying in must be a direct user transaction")
	}
	who := cur.Previous().Address()
	id := store.ID(crewID)
	c, ok := crews.Get(id)
	if !ok {
		panic(crew.ErrNoCrew.Error())
	}
	amount := envelope.RequireAtLeast(denom, joinPrice(c))

	shares, err := crews.Join(id, who, amount)
	if err != nil {
		panic(err.Error())
	}
	chain.Emit("Join",
		"crew", id.String(),
		"member", who.String(),
		"amount", strconv.FormatInt(amount, 10),
		"shares", strconv.FormatInt(shares, 10),
	)
	return shares
}

// joinPrice is the least a joiner can send and still be minted a share: the
// floor Join's envelope guard enforces, and the price a crew page quotes.
//
// The engine mints amount * totalShares / treasury, rounded down, so one whole
// share needs treasury / totalShares rounded UP. crew.Crew.PricePerShare rounds
// down, which is one ugnot short whenever the treasury is not an exact multiple
// of the share count, the ordinary state after any Fund: a joiner paying the
// quoted price passed the guard and then reverted on "buys no whole share".
// That method lives in a published package and cannot change in place, so the
// rule is here, next to the only guard that uses it. A crew nobody holds a
// share in is back at the opening price, the same branch Join takes.
func joinPrice(c *crew.Crew) int64 {
	if c.TotalShares == 0 || c.Treasury == 0 {
		return crew.InitialPricePerShare
	}
	return xmath.MulDivUp(1, c.Treasury, c.TotalShares)
}

// Fund adds what the caller sent to a crew's treasury and mints nothing, so
// every existing share is worth more afterwards.
//
// It is how revenue, a grant or a member topping the pot up arrives. Anyone may
// fund any crew, member or not: there is no way to refuse a transfer on this
// chain anyway, and pretending otherwise would only move the donation to a bank
// send the realm cannot account for.
func Fund(cur realm, crewID int64) int64 {
	// The two guards every payable call needs; see Create.
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	if !cur.Previous().IsUserCall() {
		panic("crews: paying in must be a direct user transaction")
	}
	who := cur.Previous().Address()
	amount := envelope.RequireAtLeast(denom, 1)

	if err := crews.Fund(store.ID(crewID), amount); err != nil {
		panic(err.Error())
	}
	chain.Emit("Fund",
		"crew", store.ID(crewID).String(),
		"from", who.String(),
		"amount", strconv.FormatInt(amount, 10),
	)
	return amount
}

// Propose opens an advisory question on a crew. Any member may propose, and it
// stays open for crew.VoteBlocks blocks. Returns the proposal's id.
//
// A proposal EXECUTES NOTHING. Passing one records that the crew agreed by
// share weight, and moves no coins, changes no membership and binds no code.
// Executing a payout is the next step and it is not in v0.
func Propose(cur realm, crewID int64, text string) int64 {
	who := caller(cur)
	pid, err := crews.Propose(store.ID(crewID), who, text, runtime.ChainHeight())
	if err != nil {
		panic(err.Error())
	}
	chain.Emit("Propose",
		"crew", store.ID(crewID).String(),
		"proposal", pid.String(),
		"author", who.String(),
	)
	return int64(pid)
}

// Vote records the caller's ballot, weighted by the shares they hold at this
// moment. One ballot per member, changeable while the proposal is open.
func Vote(cur realm, proposalID int64, yes bool) {
	who := caller(cur)
	pid := store.ID(proposalID)
	if err := crews.Vote(pid, who, yes, runtime.ChainHeight()); err != nil {
		panic(err.Error())
	}
	chain.Emit("Vote",
		"proposal", pid.String(),
		"voter", who.String(),
		"yes", strconv.FormatBool(yes),
	)
}

// Close records a proposal as passed or failed once its deadline has gone by,
// and returns which. Anyone may call it: closing is bookkeeping, not authority.
func Close(cur realm, proposalID int64) bool {
	pid := store.ID(proposalID)
	passed, err := crews.Close(pid, runtime.ChainHeight())
	if err != nil {
		panic(err.Error())
	}
	chain.Emit("Close", "proposal", pid.String(), "passed", strconv.FormatBool(passed))
	return passed
}

// Ragequit burns every share the caller holds, credits them their pro-rata
// slice of the treasury and removes them from the crew. Returns the amount
// credited, which [Withdraw] collects.
//
// Nobody has to agree. That is what makes a share mean something: the exit is
// priced by the same number that votes, and a member outvoted on everything can
// still leave with what they put in plus their part of what the crew built.
func Ragequit(cur realm, crewID int64) int64 {
	who := caller(cur)
	id := store.ID(crewID)
	shares, amount, err := crews.Ragequit(id, who)
	if err != nil {
		panic(err.Error())
	}
	chain.Emit("Ragequit",
		"crew", id.String(),
		"member", who.String(),
		"shares", strconv.FormatInt(shares, 10),
		"amount", strconv.FormatInt(amount, 10),
	)
	return amount
}

// Withdraw sends the caller everything they have been credited, and returns it.
//
// The credit is zeroed before the coins move, so a reentrant call finds nothing
// left to take. Nothing in this realm ever pushes value: one address that
// cannot be paid must not be able to wedge everybody else.
func Withdraw(cur realm) int64 {
	who := caller(cur)
	amount, err := crews.Withdraw(who)
	if err != nil {
		panic(err.Error())
	}

	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), who, chain.NewCoins(chain.NewCoin(denom, amount)))

	chain.Emit("Withdraw", "payee", who.String(), "amount", strconv.FormatInt(amount, 10))
	return amount
}

// Get returns a crew's name, the height it was created at, how many members it
// has, its total shares and its treasury in ugnot.
//
// Flat values rather than the crew itself: handing out a pointer to live state
// is a mutation handle nothing checks, and a struct is not something a wallet
// can decode anyway.
func Get(crewID int64) (string, int64, int, int64, int64) {
	c, ok := crews.Get(store.ID(crewID))
	if !ok {
		return "", 0, 0, 0, 0
	}
	return c.Name, c.CreatedAt, c.MemberCount(), c.TotalShares, c.Treasury
}

// Count is how many crews exist.
func Count() int { return crews.Len() }

// SharesOf is how many shares who holds in a crew.
func SharesOf(crewID int64, who address) int64 {
	c, _ := crews.Get(store.ID(crewID))
	return c.SharesOf(who)
}

// MemberCount is how many people are in a crew.
func MemberCount(crewID int64) int {
	c, _ := crews.Get(store.ID(crewID))
	return c.MemberCount()
}

// Treasury is what a crew holds, in ugnot. The coins themselves sit at this
// realm's single address: see the package doc on custody.
func Treasury(crewID int64) int64 {
	c, _ := crews.Get(store.ID(crewID))
	if c == nil {
		return 0
	}
	return c.Treasury
}

// ValuePerShare is what one of a crew's shares is worth in ugnot, rounded down.
func ValuePerShare(crewID int64) int64 {
	c, _ := crews.Get(store.ID(crewID))
	return c.ValuePerShare()
}

// ProposalOf returns a proposal's crew, author, text, deadline and whether it
// has been closed and passed.
func ProposalOf(proposalID int64) (int64, address, string, int64, bool, bool) {
	p, ok := crews.Proposal(store.ID(proposalID))
	if !ok {
		return 0, "", "", 0, false, false
	}
	return int64(p.CrewID), p.Author, p.Text, p.Deadline, p.Closed, p.Passed
}

// Tally is a proposal's share-weighted yes and no.
func Tally(proposalID int64) (int64, int64) {
	p, ok := crews.Proposal(store.ID(proposalID))
	if !ok {
		return 0, 0
	}
	return p.Yes, p.No
}

// CreditOf is what an address can withdraw right now, in ugnot.
func CreditOf(who address) int64 { return crews.CreditOf(who) }

// TotalOwed is every outstanding credit, which is the part of this realm's
// balance that belongs to people who have already left.
func TotalOwed() int64 { return crews.TotalOwed() }

// caller is the address that called us, checked the one way that is safe.
func caller(cur realm) address {
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	return cur.Previous().Address()
}

package crews

import (
	"strconv"
	"strings"
	"testing"

	"chain"

	"gno.land/p/nym-moultest123/x/social/crew/v0"
	"gno.land/p/nt/uassert/v0"
	"gno.land/p/nt/urequire/v0"
)

// The price a crew page shows a joiner, and the floor Join's envelope guard
// enforces, must both be exactly the least amount that mints a whole share.
//
// Join mints amount * totalShares / treasury, rounded down, so that amount is
// treasury / totalShares rounded UP. Rounded down instead, it is one ugnot
// short whenever the treasury is not an exact multiple of the share count,
// which is the ordinary state after any Fund: the page quotes a price, the
// guard accepts it, and the join reverts on "buys no whole share".
//
// The table is over that rule, not over one input: awkward remainders where
// floor and ceiling differ, exact multiples where they must not, and a crew
// everybody left, where the opening price applies.
func TestTheShownPriceBuysAShareAndOneLessIsRefusedByTheGuard(cur realm, t *testing.T) {
	cases := []struct {
		name   string
		create int64 // what the founder pays in, at the opening price
		fund   int64 // then funded with this, which mints nothing
		leave  bool  // then the founder ragequits, leaving an empty crew
		want   int64 // the least amount that mints one share
	}{
		{"treasury 3001 over 2 shares", 2000, 1001, false, 1501},
		{"treasury 3001 over 3 shares", 3000, 1, false, 1001},
		{"ten GNOT and seven ugnot over 10000 shares", tenGNOT, 7, false, 1001},
		{"ten GNOT and 999 ugnot over 10000 shares", tenGNOT, 999, false, 1001},
		{"exact multiple at the opening price", tenGNOT, 0, false, 1000},
		{"exact multiple after doubling", tenGNOT, tenGNOT, false, 2000},
		{"a single share", 1000, 0, false, 1000},
		{"everybody left", 1000, 0, true, crew.InitialPricePerShare},
	}
	for _, tc := range cases {
		reset()
		id := create(cur, alice, tc.create, "crew")
		if tc.fund > 0 {
			fund(cur, carol, tc.fund, id)
		}
		if tc.leave {
			testing.SetRealm(testing.NewUserRealm(alice))
			Ragequit(cross(cur), id)
		}

		// The oracle, independent of the code under test: the least a with
		// a * shares >= treasury, or the opening price when nobody holds one.
		_, _, _, shares, treasury := Get(id)
		oracle := crew.InitialPricePerShare
		if shares > 0 && treasury > 0 {
			oracle = treasury / shares
			if treasury%shares != 0 {
				oracle++
			}
		}
		urequire.Equal(t, tc.want, oracle, tc.name+": the table agrees with the rule")

		page := Render("crew/" + strconv.FormatInt(id, 10))
		uassert.Equal(t, tc.want, shownPrice(t, page),
			tc.name+": the page quotes what buys a share: "+page)

		// One ugnot under it is refused by the envelope guard, which names the
		// real price, rather than by Join after the guard let it through.
		testing.IssueCoins(realmAddr, chain.Coins{{denom, tc.want - 1}})
		testing.SetOriginSend(chain.Coins{{denom, tc.want - 1}})
		testing.SetRealm(testing.NewUserRealm(bob))
		uassert.AbortsContains(t, cur, "costs at least "+strconv.FormatInt(tc.want, 10)+denom,
			func() { Join(cross(cur), id) }, tc.name+": the guard refuses one ugnot short")

		// Exactly the quoted price buys exactly one share.
		got := join(cur, bob, tc.want, id)
		uassert.Equal(t, int64(1), got, tc.name+": the quoted price mints one share")
	}
}

// shownPrice reads the price cell of a crew page's summary table, the first
// row after the header that starts with "| members", in ugnot. It is keyed on
// the row's position, not the column's title, so it reads the same cell
// whatever that column is called.
func shownPrice(t *testing.T, page string) int64 {
	lines := strings.Split(page, "\n")
	for i, l := range lines {
		if !strings.HasPrefix(l, "| members") {
			continue
		}
		urequire.True(t, i+2 < len(lines), "the summary table has a row: "+page)
		cells := strings.Split(lines[i+2], "|")
		urequire.Equal(t, 6, len(cells), "four cells: "+lines[i+2])
		return parseGNOT(t, strings.TrimSpace(cells[4]))
	}
	t.Fatalf("no summary table on the crew page: %s", page)
	return 0
}

// parseGNOT turns num.GNOTf's "1.0015 GNOT" back into ugnot.
func parseGNOT(t *testing.T, s string) int64 {
	urequire.True(t, strings.HasSuffix(s, " GNOT"), "a GNOT amount: "+s)
	s = strings.TrimSuffix(s, " GNOT")
	whole, frac := s, ""
	if i := strings.Index(s, "."); i >= 0 {
		whole, frac = s[:i], s[i+1:]
	}
	urequire.True(t, len(frac) <= 6, "at most six decimals: "+s)
	frac += strings.Repeat("0", 6-len(frac))
	w, err := strconv.ParseInt(whole, 10, 64)
	urequire.NoError(t, err, s)
	f, err := strconv.ParseInt(frac, 10, 64)
	urequire.NoError(t, err, s)
	return w*1000000 + f
}

package crews

import (
	"strconv"

	"chain/runtime"

	"gno.land/p/nym-moultest123/kit/num/v0"
	"gno.land/p/nym-moultest123/kit/store/v0"
	"gno.land/p/nym-moultest123/kit/ui/v0"
	"gno.land/p/nym-moultest123/md/v0"
	"gno.land/p/nym-moultest123/realmpath/v0"
	"gno.land/p/nym-moultest123/x/social/crew/v0"
	"gno.land/p/nym-moultest123/xmath/v1"
)

// Render routes three views: the index, one crew, and one proposal.
func Render(path string) string {
	req := realmpath.Parse(path)

	switch req.PathPart(0) {
	case "":
		return renderIndex()
	case "crew":
		return renderCrew(req.PathPart(1))
	case "proposal":
		return renderProposal(req.PathPart(1))
	default:
		return md.H1("Not found") + "No such view: " + ui.Inline(req.Path)
	}
}

func renderIndex() string {
	out := md.H1("Crews")
	out += "Three to fifteen people with a shared pot, a way to decide, and a way to " +
		"leave with their share. One transaction to start one.\n\n"

	t := ui.NewTable("crews", "proposals", "owed to people who left")
	t.Row(
		strconv.Itoa(crews.Len()),
		strconv.Itoa(crews.ProposalCount()),
		num.GNOTf(crews.TotalOwed()),
	)
	out += t.String()

	out += md.H2("The crews")
	out += crewTable(crews.List(IndexCrews))

	out += "\n" + ui.Action("Start a crew", "Create", "name", "") + "\n"

	out += md.H2("How a share works")
	out += md.BulletList([]string{
		"A share is the vote weight and the claim on the treasury at once. There is no second token.",
		"Joining mints shares at what a share is worth NOW: " +
			md.InlineCode("amount * totalShares / treasury") +
			", rounded down, so a late joiner cannot buy into value the others built.",
		"Ragequitting burns every share you hold and credits you " +
			md.InlineCode("shares * treasury / totalShares") +
			", rounded down. Nobody has to agree.",
		"Both round in the crew's favour. The last member out holds every share, " +
			"so the treasury still empties to the last ugnot.",
		"A proposal is advisory text. Passing one records agreement and executes nothing.",
	})

	out += md.H2("Custody")
	out += "One realm address holds every crew's treasury, with per-crew accounting " +
		"inside. A bug in that accounting is a bug across crews, not inside one. " +
		"The fix is one realm per crew, and it is v1.\n"

	return out
}

func renderCrew(raw string) string {
	id, ok := store.ParseID(raw)
	if !ok {
		return md.H1("Crews") + "Not a crew id: " + ui.Inline(raw)
	}
	c, found := crews.Get(id)
	if !found {
		return md.H1("Crews") + "No crew #" + id.String()
	}

	out := md.H1(ui.Inline(c.Name))
	out += md.Italic("crew #"+id.String()+" · opened at block "+
		strconv.FormatInt(c.CreatedAt, 10)) + "\n\n"

	t := ui.NewTable("members", "shares", "treasury", "to join")
	t.Row(
		strconv.Itoa(c.MemberCount())+" of "+strconv.Itoa(crew.MaxMembers),
		strconv.FormatInt(c.TotalShares, 10),
		num.GNOTf(c.Treasury),
		num.GNOTf(joinPrice(c)),
	)
	out += t.String()

	out += md.H2("Members")
	if c.MemberCount() == 0 {
		out += ui.Empty("Everybody has left. The next member in pays the opening price again.")
	} else {
		m := ui.NewTable("member", "shares", "weight", "worth")
		for _, who := range c.Members() {
			shares := c.SharesOf(who)
			m.Row(
				ui.Addr(who),
				strconv.FormatInt(shares, 10),
				num.Pct(xmath.MulDiv(shares, 10000, c.TotalShares)),
				num.GNOTf(xmath.MulDiv(shares, c.Treasury, c.TotalShares)),
			)
		}
		out += m.String()
	}

	out += md.H2("Proposals")
	out += proposalTable(c.Proposals())
	out += "\nA proposal is advisory text. Passing one records that the crew agreed " +
		"by share weight, and executes nothing.\n"

	out += "\n" + ui.Join(" · ",
		ui.Action("Join", "Join", "crewID", id.String()),
		ui.Action("Fund", "Fund", "crewID", id.String()),
		ui.Action("Propose", "Propose", "crewID", id.String(), "text", ""),
		ui.Action("Ragequit", "Ragequit", "crewID", id.String()),
	) + "\n"
	return out
}

func renderProposal(raw string) string {
	pid, ok := store.ParseID(raw)
	if !ok {
		return md.H1("Crews") + "Not a proposal id: " + ui.Inline(raw)
	}
	p, found := crews.Proposal(pid)
	if !found {
		return md.H1("Crews") + "No proposal #" + pid.String()
	}

	out := md.H1("Proposal #" + pid.String())
	out += md.Blockquote(ui.Inline(p.Text)) + "\n"

	crewName := "crew #" + p.CrewID.String()
	if c, ok := crews.Get(p.CrewID); ok {
		crewName = c.Name
	}
	out += md.Italic("by "+ui.Addr(p.Author)+" · in "+
		md.Link(ui.ShortN(crewName, crew.ExcerptLen, 0), crewURL(p.CrewID))) + "\n\n"

	now := runtime.ChainHeight()
	t := ui.NewTable("state", "yes", "no", "voters")
	t.Row(
		state(p, now),
		strconv.FormatInt(p.Yes, 10),
		strconv.FormatInt(p.No, 10),
		strconv.Itoa(p.Voters()),
	)
	out += t.String()

	if p.Open(now) {
		out += "\n" + ui.Join(" · ",
			ui.Action("Vote yes", "Vote", "proposalID", pid.String(), "yes", "true"),
			ui.Action("Vote no", "Vote", "proposalID", pid.String(), "yes", "false"),
		) + "\n"
	} else if !p.Closed {
		out += "\n" + ui.Action("Close it", "Close", "proposalID", pid.String()) + "\n"
	}
	return out
}

// crewTable lists crews, newest first.
func crewTable(items []crew.Listing) string {
	t := ui.NewTable("crew", "members", "shares", "treasury")
	for _, it := range items {
		t.Row(
			// ShortN truncates without escaping and md.Link escapes what it
			// is given: ui.Inline here would escape twice and render the
			// backslashes. A pipe is what md.Link's escaper does NOT cover,
			// which is why crew.ValidName refuses one at write time.
			md.Link(ui.ShortN(it.Crew.Name, crew.ExcerptLen, 0), crewURL(it.ID)),
			strconv.Itoa(it.Crew.MemberCount()),
			strconv.FormatInt(it.Crew.TotalShares, 10),
			num.GNOTf(it.Crew.Treasury),
		)
	}
	return t.OrEmpty("No crews yet.")
}

// proposalTable lists a crew's proposals, newest first.
//
// The link title is the id and not the text, which is the opposite of
// crewTable and deliberate: a proposal's text is free prose and may contain a
// pipe, md.Link's escaper leaves pipes alone, and a pipe in a link title inside
// a table cell opens a column. So the chrome carries the link and the prose
// goes through ui.Cell, which is the escaper that knows it is in a table.
func proposalTable(ids []store.ID) string {
	now := runtime.ChainHeight()
	// Finding 325-cost-at-caps-1: this rendered every proposal a crew has
	// ever had, and proposing is open to every member with no delete path.
	// Newest first already, so the bound is on where the walk stops.
	total := len(ids)
	stop := 0
	if total > IndexProposals {
		stop = total - IndexProposals
	}
	t := ui.NewTable("#", "proposal", "state", "yes", "no")
	for i := total - 1; i >= stop; i-- {
		p, ok := crews.Proposal(ids[i])
		if !ok {
			continue
		}
		t.Row(
			md.Link("#"+ids[i].String(), proposalURL(ids[i])),
			// Cut on a rune boundary first, escape once after: escaping
			// first and cutting after can strand a lone backslash.
			ui.Cell(ui.ShortN(p.Text, crew.ExcerptLen, 0)),
			state(p, now),
			strconv.FormatInt(p.Yes, 10),
			strconv.FormatInt(p.No, 10),
		)
	}
	out := t.OrEmpty("Nothing has been proposed yet.")
	if total > IndexProposals {
		out += md.Italic("Showing the newest "+strconv.Itoa(IndexProposals)+" of "+
			strconv.Itoa(total)+" proposals.") + "\n"
	}
	return out
}

// state is the one word a proposal is in at height now.
func state(p *crew.Proposal, now int64) string {
	switch {
	case p.Open(now):
		return "open until " + strconv.FormatInt(p.Deadline, 10)
	case !p.Closed:
		return "awaiting a close"
	case p.Passed:
		return "passed"
	default:
		return "failed"
	}
}

// crewURL is the gnoweb path of one crew.
func crewURL(id store.ID) string { return realmURL() + ":crew/" + id.String() }

// proposalURL is the gnoweb path of one proposal.
func proposalURL(id store.ID) string { return realmURL() + ":proposal/" + id.String() }

// realmURL is this realm's gnoweb path. The chain domain is the first element
// of a package path and a gnoweb path is the rest of it, so this is a prefix
// strip and not a hostname the realm has to know.
func realmURL() string {
	for i := 0; i < len(realmPath); i++ {
		if realmPath[i] == '/' {
			return realmPath[i:]
		}
	}
	return "/" + realmPath
}

// Package counter is the smallest realm that still proves the whole pipeline:
// it is deployed, approved, called with an int and a string, read back through
// Render and through QEval, and made to abort on purpose.
//
// It imports nothing but strconv, deliberately. A smoke test that fails because
// a stdlib package moved between chain versions reports a problem with itself,
// not with the chain, and that is the one failure mode this file must not have.
package counter

import "strconv"

var (
	count int
	note  string
)

// Increment adds n and returns the new total. It panics on a non-positive n,
// which is what the scenario's expect_fail step exercises: a realm that aborts
// is a different outcome from one that is unreachable, and only a real chain
// tells the two apart.
func Increment(cur realm, n int) int {
	if n <= 0 {
		panic("increment must be positive")
	}
	count += n
	return count
}

// SetNote stores a short string, so the scenario covers a string argument
// surviving the round trip through amino and back out of Render.
func SetNote(cur realm, s string) {
	if len(s) > 64 {
		panic("note too long")
	}
	note = s
}

// Get is the QEval target: an int return, read with no gas and no key.
func Get() int { return count }

func Render(path string) string {
	if path == "note" {
		return "note: " + note
	}
	return "count: " + strconv.Itoa(count)
}
